<?php
require_once __DIR__ . '/../../app/auth.php';
require_once __DIR__ . '/../../app/view.php';
$db = database(); $user = admin_user($db); $companyId = (int)$user['company_id'];
$counts = [];
foreach (['projects','tasks','employees','customers','departments','leads'] as $table) $counts[$table] = (int)db_one($db,"SELECT COUNT(*) AS count FROM `$table` WHERE company_id = ?",[$companyId])['count'];
$pending = (int)db_one($db,"SELECT COUNT(*) AS count FROM tasks WHERE company_id = ? AND status != 'completed'",[$companyId])['count'];
$completed = (int)db_one($db,"SELECT COUNT(*) AS count FROM tasks WHERE company_id = ? AND status = 'completed'",[$companyId])['count'];
$projects = db_rows($db,'SELECT id, projectName, status, endDate FROM projects WHERE company_id = ? ORDER BY updated_at DESC, id DESC LIMIT 4',[$companyId]);
$tasks = db_rows($db,"SELECT id, title, due_date, priority FROM tasks WHERE company_id = ? AND status != 'completed' ORDER BY due_date, id LIMIT 5",[$companyId]);
$steps = [['Email verified',true,''],['Create a department',$counts['departments']>0,'departments'],['Add your team',$counts['employees']>0,'employees'],['Start your first project',$counts['projects']>0,'projects']];
$done = count(array_filter($steps,fn($step)=>$step[1]));
suite_start('Overview','overview',$user);
?>
<div class="page-heading"><div><span class="eyebrow"><?= e(date('l, j F Y')) ?></span><h1>Your business, at a glance.</h1><p>Welcome to <?= e($user['company_name']) ?>. Let’s make room for a productive day.</p></div><div class="heading-actions"><a class="button secondary small" href="/users/admin/modules.php">Explore tools</a><a class="button small" href="/users/admin/workspace.php?module=tasks&amp;action=new"><?= icon('plus') ?> Create task</a></div></div>
<div class="stats-grid"><?php foreach ([['Active projects',$counts['projects'],'folder','projects','See your projects'],['Open tasks',$pending,'task','tasks',$completed . ' completed'],['Your people',$counts['employees'],'users','employees','View your team'],['Customers',$counts['customers'],'chart','customers','Build your relationships']] as [$label,$count,$glyph,$module,$detail]): ?><section class="stat-card"><div class="stat-label"><span><?= e($label === 'Active projects' ? 'Total projects' : $label) ?></span><?= icon($glyph) ?></div><div class="stat-value"><?= number_format($count) ?></div><div class="stat-foot"><a class="text-link" href="/users/admin/workspace.php?module=<?= e($module) ?>"><?= e($detail) ?> <span aria-hidden="true">↗</span></a></div></section><?php endforeach; ?></div>
<div class="dashboard-columns"><div><section class="panel"><div class="panel-head"><h2>Projects in motion</h2><a class="text-link" href="/users/admin/workspace.php?module=projects">View all <?= icon('arrow') ?></a></div><?php if (!$projects): ?><div class="empty-state"><?= icon('folder') ?><h3>Your next big thing starts here.</h3><p>Create your first project to bring your plans, people, and next steps together.</p><a class="button small secondary" href="/users/admin/workspace.php?module=projects&amp;action=new"><?= icon('plus') ?> Create a project</a></div><?php else: ?><ul class="record-list"><?php foreach ($projects as $project): ?><li><span class="record-icon"><?= icon('folder') ?></span><div><strong><a class="text-link" href="/users/admin/workspace.php?module=projects&amp;action=edit&amp;id=<?= (int)$project['id'] ?>"><?= e($project['projectName']) ?></a></strong><small><?= $project['endDate'] ? 'Due ' . e(date('j M Y',strtotime($project['endDate']))) : 'No due date set' ?></small></div><span class="badge <?= e(preg_replace('/[^a-z]/','',strtolower($project['status'] ?? ''))) ?>"><?= e($project['status'] ?: 'Planned') ?></span></li><?php endforeach; ?></ul><?php endif; ?></section>
<section class="panel"><div class="panel-head"><h2>Your next priorities</h2><a class="text-link" href="/users/admin/workspace.php?module=tasks">All tasks <?= icon('arrow') ?></a></div><?php if (!$tasks): ?><div class="empty-state" style="padding:30px 20px"><?= icon('task') ?><h3>A clear list. A clearer head.</h3><p><?= $counts['tasks'] ? 'All your tasks are complete. Add the next step when you’re ready.' : 'Add the next steps for your project and give each one a due date.' ?></p><a class="text-link" href="/users/admin/workspace.php?module=tasks&amp;action=new">Add a task <?= icon('plus') ?></a></div><?php else: ?><ul class="record-list"><?php foreach ($tasks as $task): ?><li><span class="record-icon"><?= icon('task') ?></span><div><strong><a class="text-link" href="/users/admin/workspace.php?module=tasks&amp;action=edit&amp;id=<?= (int)$task['id'] ?>"><?= e($task['title']) ?></a></strong><small><?= $task['due_date'] < date('Y-m-d') ? 'Overdue · ' : 'Due ' ?><?= e(date('j M',strtotime($task['due_date']))) ?></small></div><span class="badge <?= e($task['priority']) ?>"><?= e($task['priority']) ?></span></li><?php endforeach; ?></ul><?php endif; ?></section></div>
<aside><section class="welcome-panel"><?= icon('spark') ?><span class="eyebrow" style="font-size:8px">MAKE YOURSELF AT HOME</span><h2>A little setup.<br>A much simpler day.</h2><p>Your workspace grows with your business. Start with a project, or explore the tools that fit your day.</p><a class="button small secondary" href="/users/admin/modules.php">Find your next tool <?= icon('arrow') ?></a></section><section class="panel"><div class="panel-head"><h2>Your workspace checklist</h2><span class="badge"><?= $done ?> of 4</span></div><div class="panel-body"><ul class="checklist"><?php foreach ($steps as $index=>[$label,$complete,$module]): ?><li class="<?= $complete ? 'done' : '' ?>"><span><?= $complete ? icon('check') : $index+1 ?></span><span><?= e($label) ?></span><?php if (!$complete): ?><a href="/users/admin/workspace.php?module=<?= e($module) ?>&amp;action=new" aria-label="<?= e($label) ?>"><?= icon('arrow') ?></a><?php endif; ?></li><?php endforeach; ?></ul></div></section></aside></div>
<div class="section-title"><h2>A tool for every part of your day.</h2><a class="text-link" href="/users/admin/modules.php">See all tools →</a></div><div class="tools-grid"><?php foreach ([['leads','chart','Sales & CRM','Your next conversation, organized.'],['expenses','wallet','Finance','Keep your financial records in view.'],['applications','briefcase','Recruiting','A home for your next great hire.'],['products','box','Product development','From first idea to launch.'],['compliance','shield','Risk & compliance','Keep track of what needs attention.'],['assets','folder','Office management','A place for your everyday operations.']] as [$module,$glyph,$title,$description]): ?><a class="tool-card" href="/users/admin/workspace.php?module=<?= e($module) ?>"><div class="feature-icon"><?= icon($glyph) ?></div><h3><?= e($title) ?></h3><p><?= e($description) ?></p></a><?php endforeach; ?></div>
<?php suite_end(); ?>
